// --- configuration -------------------------------------------------
// Single configuration source for the whole workflow: base URL of the
// FastAPI service (no trailing slash, no /leads) AND the lead
// qualification threshold (integer 0-100). Override them with the
// LEAD_API_BASE_URL / LEAD_QUALIFIED_THRESHOLD environment variables of
// the n8n process. n8n 2.x blocks $env in expressions and Code nodes by
// default (N8N_BLOCK_ENV_ACCESS_IN_NODE), so each lookup is probed
// defensively and falls back to the documented defaults below. The
// *Source fields record which source was used and are visible in every
// execution; downstream nodes read this configuration from this node's
// output with $('Prepare Lead Payload') - the values are never repeated
// in another node.
const DEFAULT_API_BASE_URL = 'http://localhost:8000';
// Initial business rule, NOT an empirically validated sales threshold:
// the heuristic scorer starts at a baseline of 45; representative leads
// score 12-35 (junk), 63 (corporate inbound without an intent keyword)
// and 77-100 (explicit buying intent), so 70 sits in the observed 63-77
// gap and requires net positive signal above baseline. Tune it with
// LEAD_QUALIFIED_THRESHOLD (0-100).
const DEFAULT_QUALIFIED_THRESHOLD = 70;

let apiBaseUrl = DEFAULT_API_BASE_URL;
let apiBaseUrlSource = 'workflow-default';
try {
  const fromEnv = $env.LEAD_API_BASE_URL;
  if (fromEnv) {
    apiBaseUrl = String(fromEnv).replace(/\/+$/, '');
    apiBaseUrlSource = 'environment';
  }
} catch (err) {
  // $env denied (N8N_BLOCK_ENV_ACCESS_IN_NODE) or unavailable.
  apiBaseUrlSource = 'workflow-default (n8n blocks $env access)';
}

let qualifiedThreshold = DEFAULT_QUALIFIED_THRESHOLD;
let thresholdSource = 'workflow-default';
try {
  const fromEnv = $env.LEAD_QUALIFIED_THRESHOLD;
  if (fromEnv !== undefined && fromEnv !== null && String(fromEnv).trim() !== '') {
    const parsed = Number(fromEnv);
    if (Number.isFinite(parsed) && parsed >= 0 && parsed <= 100) {
      qualifiedThreshold = parsed;
      thresholdSource = 'environment';
    } else {
      thresholdSource = 'workflow-default (invalid LEAD_QUALIFIED_THRESHOLD)';
    }
  }
} catch (err) {
  thresholdSource = 'workflow-default (n8n blocks $env access)';
}

// --- payload mapping ------------------------------------------------
// FastAPI owns validation, persistence, duplicate detection and scoring.
// This node only copies the documented contract fields out of the webhook
// body and drops everything else - no validation rules are re-implemented.
const body = $input.first().json.body || {};

const lead = {
  name: body.name ?? null,
  email: body.email ?? null,
  company: body.company ?? null,
  message: body.message ?? null,
  source: body.source || 'n8n-webhook',
  external_id: body.external_id ?? null,
};

return [{
  json: {
    lead,
    apiLeadsUrl: `${apiBaseUrl}/leads`,
    apiBaseUrlSource,
    qualifiedThreshold,
    thresholdSource,
  },
}];

// Normalize the successful (201) API response into the routing base
// result. FastAPI owns scoring - this node only copies the score it
// returned. score stays null when FastAPI could not score the lead; it
// is never coerced to 0 and never invented here.
const http = $input.first().json || {};
const body = (http.body && typeof http.body === 'object') ? http.body : {};

const rawScore = body.score;
const score = (typeof rawScore === 'number' && Number.isFinite(rawScore))
  ? rawScore
  : null;

return [{
  json: {
    apiStatus: typeof http.statusCode === 'number' ? http.statusCode : null,
    leadId: body.lead_id ?? null,
    company: body.company ?? null,
    source: body.source ?? null,
    score,
    scoreReason: body.score_reason ?? null,
  },
}];

// Qualification decision - the single place where the threshold rule is
// applied (Milestone 8). FastAPI still owns the score; this node only
// labels what FastAPI returned.
//
//   score not a finite number (null / missing)  -> manual_review, priority null
//   score >= threshold                          -> qualified,     priority "high"
//   score <  threshold                          -> not_qualified, priority "normal"
//
// The threshold comes from the configuration block of "Prepare Lead
// Payload" (one config source, never redefined here). If that config is
// missing or malformed the lead goes to manual review instead of guessing.
const config = $('Prepare Lead Payload').first().json || {};
const threshold = config.qualifiedThreshold;
const extracted = $input.first().json;
const score = extracted.score;

const thresholdOk = typeof threshold === 'number' && Number.isFinite(threshold);

let qualification;
let priority;
if (!thresholdOk || typeof score !== 'number' || !Number.isFinite(score)) {
  qualification = 'manual_review';
  priority = null;
} else if (score >= threshold) {
  qualification = 'qualified';
  priority = 'high';
} else {
  qualification = 'not_qualified';
  priority = 'normal';
}

return [{
  json: {
    ...extracted,
    qualification,
    priority,
    qualifiedThreshold: thresholdOk ? threshold : null,
    thresholdSource: config.thresholdSource ?? 'unknown',
  },
}];

// Priority-branch operational record (Milestone 9) for a qualified lead.
// The record below IS this node's output: n8n persists it in the execution
// data, where an operator can inspect it in the execution view. It is a
// workflow-native operational record, NOT an external notification - this
// environment has no email/Slack/Telegram/CRM integration and none is
// faked here. `event` names the operational action for downstream
// consumers; `summary` is the human-readable rendering of the same values.
const lead = $input.first().json || {};

const record = {
  event: 'lead_qualified',
  leadId: lead.leadId ?? null,
  company: lead.company ?? null,
  source: lead.source ?? null,
  score: lead.score ?? null,
  scoreReason: lead.scoreReason ?? null,
  qualification: lead.qualification ?? 'qualified',
  priority: lead.priority ?? null,
  reason: null,
  qualifiedThreshold: lead.qualifiedThreshold ?? null,
  thresholdSource: lead.thresholdSource ?? null,
};

const summary = [
  'HIGH PRIORITY LEAD',
  `Company: ${record.company}`,
  `Lead ID: ${record.leadId}`,
  `Score: ${record.score}`,
  `Source: ${record.source}`,
  `Qualification: ${record.qualification}`,
].join('\n');

return [{ json: { ...record, summary } }];

// Not-qualified branch operational record (Milestone 9): the score is
// below the configured threshold. Same delivery mechanism as the priority
// branch - the record is this node's output, persisted in n8n's execution
// data. Workflow-native record, not an external notification.
const lead = $input.first().json || {};

const record = {
  event: 'lead_not_qualified',
  leadId: lead.leadId ?? null,
  company: lead.company ?? null,
  source: lead.source ?? null,
  score: lead.score ?? null,
  scoreReason: lead.scoreReason ?? null,
  qualification: lead.qualification ?? 'not_qualified',
  priority: lead.priority ?? null,
  reason: null,
  qualifiedThreshold: lead.qualifiedThreshold ?? null,
  thresholdSource: lead.thresholdSource ?? null,
};

const summary = [
  'NOT QUALIFIED',
  `Company: ${record.company}`,
  `Lead ID: ${record.leadId}`,
  `Score: ${record.score}`,
  `Source: ${record.source}`,
  `Qualification: ${record.qualification}`,
].join('\n');

return [{ json: { ...record, summary } }];

// Manual-review branch operational record (Milestone 9): FastAPI could
// not score the lead (score stays null) or the qualification state could
// not be determined. The score is never replaced with 0 or a guess.
// Same delivery mechanism as the other branches - the record is this
// node's output, persisted in n8n's execution data. Workflow-native
// record, not an external notification.
const lead = $input.first().json || {};
const score = (typeof lead.score === 'number' && Number.isFinite(lead.score))
  ? lead.score
  : null;
const reason = score === null
  ? 'scoring unavailable'
  : 'qualification could not be determined';

const record = {
  event: 'lead_manual_review',
  leadId: lead.leadId ?? null,
  company: lead.company ?? null,
  source: lead.source ?? null,
  score,
  scoreReason: lead.scoreReason ?? null,
  qualification: lead.qualification || 'manual_review',
  priority: lead.priority ?? null,
  reason,
  qualifiedThreshold: lead.qualifiedThreshold ?? null,
  thresholdSource: lead.thresholdSource ?? null,
};

const summary = [
  'MANUAL REVIEW REQUIRED',
  `Company: ${record.company}`,
  `Lead ID: ${record.leadId}`,
  `Score: ${record.score}`,
  `Source: ${record.source}`,
  `Qualification: ${record.qualification}`,
  `Reason: ${record.reason}`,
].join('\n');

return [{ json: { ...record, summary } }];

// Unified operational audit event (Milestone 9): one downstream event
// representation per processed lead - execution context (when it ran, which
// execution) merged with the branch record that reached this node. The
// event stays entirely inside n8n's execution data: no database table, no
// FastAPI endpoint, no external channel. It is the hand-off point a future
// consumer (email, Slack, Telegram, CRM, analytics) would attach to, so the
// payload stays structured instead of being flattened into one string.
const record = $input.first().json || {};

return [{
  json: {
    timestamp: $now.toISO(),
    executionId: $execution.id,
    executionMode: $execution.mode,
    ...record,
  },
}];

// Telegram message for a qualified lead (Milestone 10). The text is mapped
// from the operational record that "Log Priority Route" emitted - real
// workflow fields only, never invented (no fabricated score, company,
// source or lead ID). The destination chat comes from the TELEGRAM_CHAT_ID
// environment variable of the n8n process; the bot token is NOT read here -
// it lives in n8n's credential store and is referenced by the Telegram node.
const record = $input.first().json || {};

let chatId = null;
try {
  const raw = $env.TELEGRAM_CHAT_ID;
  if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
    chatId = String(raw).trim();
  }
} catch (err) {
  // $env denied (N8N_BLOCK_ENV_ACCESS_IN_NODE): surfaced by the check below.
}
if (chatId === null) {
  throw new Error('TELEGRAM_CHAT_ID is not configured on the n8n process (set it, and N8N_BLOCK_ENV_ACCESS_IN_NODE=false to allow $env)');
}

// The Telegram node sends with parse_mode HTML, so &, < and > in real lead
// data (company names, reasons) must be escaped - Telegram would otherwise
// reject the message. Escaping does not change what a human sees.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const message = [
  '\u{1F525} HIGH-PRIORITY LEAD',
  '',
  `Company: ${esc(record.company)}`,
  `Lead ID: ${esc(record.leadId)}`,
  `Score: ${esc(record.score)}`,
  `Qualification: ${esc(record.qualification)}`,
  `Source: ${esc(record.source)}`,
  '',
  'Action: Review and contact this lead.',
].join('\n');

return [{ json: { ...record, chatId, telegramMessage: message } }];

// Telegram message for a lead that needs human review (Milestone 10):
// FastAPI could not score it (score stays null) or the qualification state
// could not be determined. Mapped from the operational record of
// "Log Manual Review" - a null score is displayed as "unavailable" and is
// never replaced by a number. Destination from the TELEGRAM_CHAT_ID env
// variable of the n8n process; the bot token stays in n8n's credential store.
const record = $input.first().json || {};

let chatId = null;
try {
  const raw = $env.TELEGRAM_CHAT_ID;
  if (raw !== undefined && raw !== null && String(raw).trim() !== '') {
    chatId = String(raw).trim();
  }
} catch (err) {
  // $env denied (N8N_BLOCK_ENV_ACCESS_IN_NODE): surfaced by the check below.
}
if (chatId === null) {
  throw new Error('TELEGRAM_CHAT_ID is not configured on the n8n process (set it, and N8N_BLOCK_ENV_ACCESS_IN_NODE=false to allow $env)');
}

// The Telegram node sends with parse_mode HTML, so &, < and > in real lead
// data (company names, reasons) must be escaped - Telegram would otherwise
// reject the message. Escaping does not change what a human sees.
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const score = (typeof record.score === 'number' && Number.isFinite(record.score))
  ? record.score
  : 'unavailable';

const message = [
  '\u26A0\uFE0F LEAD NEEDS MANUAL REVIEW',
  '',
  `Company: ${esc(record.company)}`,
  `Lead ID: ${esc(record.leadId)}`,
  `Score: ${esc(score)}`,
  `Qualification: ${esc(record.qualification)}`,
  `Source: ${esc(record.source)}`,
  '',
  `Reason: ${esc(record.reason)}.`,
].join('\n');

return [{ json: { ...record, chatId, telegramMessage: message } }];
